import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as a,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"可解释性（桥接）","description":"模型内部为什么这样输出——机制可解释性（superposition、特征、归因图）全部桥接 Learn LLM；本仓只保留应用工程师的位置感：它影响信任边界、审计承诺与「为什么这么说」的排障预期。","frontmatter":{"title":"可解释性（桥接）","description":"模型内部为什么这样输出——机制可解释性（superposition、特征、归因图）全部桥接 Learn LLM；本仓只保留应用工程师的位置感：它影响信任边界、审计承诺与「为什么这么说」的排障预期。","domain":"tech","tags":["tech","interpretability","bridge","safety"],"navOrder":91,"topicId":"interpretability","layer":"9","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/09-advanced/interpretability.md","filePath":"zh/tech/09-advanced/interpretability.md","lastUpdated":1791123021000}'),o={name:"zh/tech/09-advanced/interpretability.md"};function n(d,t,l,s,h,c){return a(),e("div",null,[...t[0]||(t[0]=[i('<blockquote><p><strong>所在组</strong>：进阶（桥接） ｜ <strong>上一组出口</strong>：能用发布门与版本化纪律长期运行 ｜ <strong>本页出口</strong>：知道该主题影响哪个工程决策、何时去 Learn LLM</p></blockquote><h1 id="可解释性-桥接" tabindex="-1">可解释性（桥接） <a class="header-anchor" href="#可解释性-桥接" aria-label="Permalink to &quot;可解释性（桥接）&quot;">​</a></h1><blockquote><p><strong>桥接页</strong>：机制可解释性（mechanistic interpretability）——superposition、稀疏自编码器、特征分解、归因图——的推导与实验在 <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>（第 7 章 · Transformer 的内部机制部分）。本仓只回答应用工程师的问题：<strong>它改变我的哪个决策，以及什么时候我需要的其实不是它。</strong></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>解决什么问题</strong>：模型是黑箱——你能观测输入与输出，但「它为什么这么说」藏在中间层。可解释性研究把中间层打开：把激活分解为可读的「特征」（features），再追踪特征之间的因果链（归因图），试图把「为什么」变成可检查的证据。</p><p><strong>为什么应用工程师要有位置感</strong>：你不是要去拆模型，而是要管理三类由黑箱引起的工程责任：</p><ul><li><strong>信任边界</strong>：多深的行为保证你敢对外承诺？「我们说不清它为什么拒绝/不拒绝」在高风险场景是合规缺口，不是学术问题。</li><li><strong>排障预期</strong>：应用层手段（评估、trace、消融）只能回答「行为变了没有」；「模型内部为什么这样」超出应用层工具箱——知道这条边界，就不会在错误的层上浪费时间。</li><li><strong>叙事校准</strong>：归因图展示的「规划」「隐藏目标」是研究工具的产物；对外沟通时把它当证据框架而不是「模型有意识」的证明。</li></ul><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>它影响的决策（不涉及代码，涉及立场）：</p><table tabindex="0"><thead><tr><th>决策</th><th>可解释性给的位置感</th></tr></thead><tbody><tr><td>高风险场景的模型选型</td><td>黑箱深度是选型成本之一：越说不清行为来源，越需要外部护栏（评估门、人工复核）补位</td></tr><tr><td>对客户/监管的审计承诺</td><td>只承诺应用层可证明的东西（trace、评估记录）；「内部机制可解释」目前是研究前沿，不是可交付物</td></tr><tr><td>「为什么输出这个」的排障</td><td>先走应用层：trace 与上下文对账（→<a href="./../08-production/observability.html">可观测性</a>）、输入消融、评估集对比；全部指向「模型就是这样」时才是本区</td></tr><tr><td>产品文案与心智模型</td><td>「特征」「回路」是研究词汇；产品语境用行为合同（schema、验收）说话</td></tr></tbody></table><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><p>（本段刻意极简：推导与实验归 Learn LLM 第 7 章。）</p><p>一句话链路：神经元同时编码多个概念（superposition，叠加）→ 用字典学习/稀疏自编码器把激活分解为单义「特征」→ 追踪特征间因果得到归因图。这是研究路线，不是应用 API——<strong>应用工程师没有可直接调用的「explain()」</strong>。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p><strong>症状 → 去哪</strong>：</p><ul><li>「输出不稳定」→ 不是本区，去 <a href="./../03-context/">03-context</a>（契约收敛自由度）。</li><li>「这次回答为什么错」→ 先 <a href="./../08-production/observability.html">可观测性</a>（trace 还原上下文）与 <a href="./../08-production/evaluation.html">评估</a>（行为边界），多数「为什么」其实是上下文问题。</li><li>「我们要向监管证明模型安全」→ <a href="./../08-production/">08-production</a> 的证据链；可解释性作为研究背景了解，不作为承诺。</li><li>确实想读懂内部机制 → Learn LLM 第 7 章（Transformer 内部机制）。</li></ul><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><h3 id="本区页面" tabindex="-1">本区页面 <a class="header-anchor" href="#本区页面" aria-label="Permalink to &quot;本区页面&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页面</th><th>主题</th></tr></thead><tbody><tr><td><a href="./reasoning-ttc.html">推理模型与 TTC</a></td><td>思考型输出的预算、延迟与停止条件</td></tr><tr><td><a href="./moe-frontier.html">MoE 与前沿架构</a></td><td>定价/速度/上下文上限的架构解释</td></tr><tr><td><a href="./multimodal.html">多模态</a></td><td>视觉等跨模态能力的最小用法与边界</td></tr></tbody></table><p>一手源（研究方原发表，不复述内容）：</p><table tabindex="0"><thead><tr><th>名称</th><th>来源</th><th>标识</th></tr></thead><tbody><tr><td>Toy Models of Superposition</td><td>Anthropic（Transformer Circuits）</td><td>arXiv:2209.10652</td></tr><tr><td>Sparse Autoencoders Find Highly Interpretable Model Directions</td><td>Cunningham et al.</td><td>arXiv:2309.08600</td></tr><tr><td>Towards Monosemanticity</td><td>Anthropic（Transformer Circuits）</td><td><a href="https://transformer-circuits.pub/2023/monosemantic-features/index.html" target="_blank" rel="noreferrer">https://transformer-circuits.pub/2023/monosemantic-features/index.html</a></td></tr><tr><td>On the Biology of a Large Language Model（归因图）</td><td>Anthropic（Transformer Circuits，2025-03）</td><td><a href="https://transformer-circuits.pub/2025/attribution-graphs/biology.html" target="_blank" rel="noreferrer">https://transformer-circuits.pub/2025/attribution-graphs/biology.html</a></td></tr></tbody></table><p>（retrievedAt 2026-09-01；后续进展以 Transformer Circuits 与各实验室发表为准，本仓不维护快照。）</p><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>特征分解、归因图方法与实验：<a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> 第 7 章（Transformer 内部机制）。</li><li>应用侧真正可落地的「为什么」工具：trace 与评估（<a href="./../08-production/">08-production</a>）。</li></ul>',24)])])}const g=r(o,[["render",n]]);export{f as __pageData,g as default};
